namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed initial fake data
        Add("Welcome to the notification center!");
        Add("Your profile was updated successfully.");
        Add("New comment on your post.");
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally by the polling loop on the page.
    /// </summary>
    public void SimulateIncoming()
    {
        // ~30 % chance a new notification appears each poll
        if (Random.Shared.Next(0, 100) < 30)
        {
            string[] samples =
            [
                "You have a new follower!",
                "Your build succeeded.",
                "Deployment to production completed.",
                "Reminder: standup in 10 minutes.",
                "Someone mentioned you in a comment.",
                "Your subscription is about to expire.",
            ];

            Add(samples[Random.Shared.Next(samples.Length)]);
        }
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during both prerender AND interactive start.
    protected override void OnInitialized()
    {
        // Only load from the service when the list is empty (i.e., first/prerender pass).
        // On the interactive pass the framework preserves component state from prerender,
        // so _notifications is already populated — skip the fetch.
        if (_notifications.Count == 0)
        {
            _notifications = NotificationService.GetAll();
            _lastSeenId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
        }
    }

    // Called only once the circuit is live (never during static SSR prerender).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            NotificationService.SimulateIncoming();

            var newer = NotificationService.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

